"""
LLM client for mybrain pipeline.

Two tiers:
- Free: OpenRouter (qwen-2.5-72b-instruct) using runtime key
- Zen: opencode.ai — primary opencode-go/claude-sonnet-4, fallback opencode-zen/claude-sonnet-4
"""

from __future__ import annotations

import json
import os
import sys
import time
from pathlib import Path
from typing import Any, Dict, List, Optional

import httpx


def _decimal_safe_default(obj):
    """JSON default handler: DuckDB returns Decimal for DECIMAL columns."""
    from decimal import Decimal
    if isinstance(obj, Decimal):
        return float(obj)
    raise TypeError(f"Object of type {obj.__class__.__name__} is not JSON serializable")


def _dumps(obj, **kw):
    """json.dumps that tolerates Decimal values from DuckDB results."""
    return json.dumps(obj, default=_decimal_safe_default, **kw)


def _parse_llm_json(text: str):
    """Parse LLM response that may contain code blocks or Python-style syntax."""
    text = text.strip()
    if text.startswith("```"):
        lines = text.split("\n")
        text = "\n".join(l for l in lines if not l.startswith("```"))
        text = text.strip()
    try:
        return json.loads(text)
    except (json.JSONDecodeError, ValueError, TypeError):
        pass
    import ast

    try:
        return ast.literal_eval(text)
    except (ValueError, SyntaxError, TypeError):
        pass
    import re

    escaped = re.sub(r"(?<!\\)'", '"', text)
    try:
        return json.loads(escaped)
    except (json.JSONDecodeError, ValueError, TypeError):
        pass
    # Try to extract JSON from text containing reasoning preamble
    for start_char, end_char in [("{", "}"), ("[", "]")]:
        idx = text.find(start_char)
        if idx >= 0:
            depth = 0
            for i in range(idx, len(text)):
                if text[i] == start_char:
                    depth += 1
                elif text[i] == end_char:
                    depth -= 1
                if depth == 0:
                    extracted = text[idx : i + 1]
                    try:
                        import ast as _ast

                        return _ast.literal_eval(extracted)
                    except Exception:
                        pass
                    try:
                        import re as _re

                        esc = _re.sub(r"(?<!\\)'", '"', extracted)
                        return json.loads(esc)
                    except Exception:
                        break
    raise ValueError(f"Could not parse LLM output as JSON: {text[:200]}")


class JevClient:
    """TypeSafe Jev client for structured decisions via OpenRouter.

    Jev is a System One model that returns typed, probabilistic decisions
    instead of generated text. It's optimized for classification, routing,
    scoring, and verification tasks.

    Performance: 70-500ms latency, $0.042/M input tokens, output free.
    No hallucination in output format — returns only values you define.

    Usage:
        jev = JevClient()
        result = jev.evaluate(
            state="Task: Buy groceries for family dinner",
            questions={
                "domain": {
                    "type": "choice",
                    "instructions": "Which domain?",
                    "criteria": {
                        "family": "Family-related tasks",
                        "finance": "Money matters",
                        "home": "Household tasks"
                    }
                },
                "urgency": {
                    "type": "score",
                    "instructions": "How urgent?",
                    "criteria": ["low", "medium", "high", "critical"]
                },
                "involves_money": {
                    "type": "noul",
                    "instructions": "Does this involve spending money?"
                }
            }
        )
        # result["domain"]["choice"] == "family"
        # result["domain"]["confidence"] == 0.85
        # result["urgency"]["score"] == 1.5  (between medium and high)
        # result["involves_money"]["noul"] == 0.92

    Note: Escalate to full LLM when domain confidence < 0.5.
    """

    # Jev decisions endpoint (not chat/completions)
    JEV_ENDPOINT = "https://openrouter.ai/api/alpha/decisions"
    JEV_MODEL = "typesafe/jev-1.13"

    # Domain taxonomy from db.py seed_domains
    DOMAINS = [
        "family", "finance", "health", "tech", "home", "work",
        "media", "ideas", "fitness", "education", "social", "reflection"
    ]

    PRIORITIES = ["dormant", "low", "medium", "high", "critical"]
    LIFECYCLES = ["active", "stalled", "completed", "reference", "someday"]
    SENTIMENTS = ["very_negative", "negative", "neutral", "positive", "very_positive"]
    ENTITY_TYPES = ["person", "organization", "place", "concept", "tool"]

    def __init__(self):

        # Try multiple sources for OpenRouter API key
        self.api_key = (
            os.environ.get("OPENROUTER_API_KEY") or
            self._read_first_line(Path.home() / ".config" / "opencode" / ".openrouter-key") or
            self._read_first_line(Path.home() / ".agents" / "keys" / ".openrouter-key")
        )

    @staticmethod
    def _read_first_line(path: Path) -> Optional[str]:
        try:
            return path.read_text().strip()
        except (FileNotFoundError, OSError):
            return None

    def evaluate(
        self,
        state: str,
        questions: Dict[str, Dict]
    ) -> Dict[str, Any]:
        """
        Evaluate typed questions against state.

        Args:
            state: Unstructured context (task text, document, etc.)
            questions: Dict of question_id -> question_spec
                question_spec format:
                - type: "choice" | "score" | "noul"
                - instructions: str (required)
                - For choice: each option_id -> description mapping
                - For score: "criteria" -> List[str] of levels
                - For noul: "true" -> str, "false" -> str (optional labels)

        Returns:
            Dict of question_id -> answer
                answer format depends on type:
                - choice: {choice, probabilities, confidence}
                - score: {score, legend, probabilities, confidence}
                - noul: {noul} (probability 0-1)

        Raises:
            ValueError: If API key missing or API error
        """
        if not self.api_key:
            raise ValueError("OPENROUTER_API_KEY not found")

        payload = {
            "model": self.JEV_MODEL,
            "state": state,
            "questions": questions
        }

        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "HTTP-Referer": "https://github.com/mybrain",
            "X-Title": "mybrain LifeOS"
        }

        try:
            with httpx.Client(timeout=30.0) as client:
                resp = client.post(self.JEV_ENDPOINT, json=payload, headers=headers)
                resp.raise_for_status()
                data = resp.json()
            # Jev returns: {"answers": {question_id: {type, choice/score/noul, ...}}}
            if "answers" in data:
                return data["answers"]
            return data

        except httpx.HTTPStatusError as e:
            print(f"Jev API error: {e.response.status_code} — {e.response.text}", file=sys.stderr)
            raise ValueError(f"Jev API error: {e.response.status_code}")
        except json.JSONDecodeError as e:
            print(f"Jev response parse error: {e}\n{e.response.text if hasattr(e, 'response') else ''}", file=sys.stderr)
            raise ValueError(f"Jev response parse error: {e}")

    def classify_task(
        self,
        title: str,
        notes: str = "",
        list_name: str = "",
        created: str = "",
        status: str = ""
    ) -> Dict[str, Any]:
        """
        Classify a task using Jev for structured decisions.

        Returns classification compatible with existing LLMClient.classify_task output,
        plus confidence scores and flags.
        """
        state = f"""Task: {title}
Notes: {notes or '(none)'}
List: {list_name}
Created: {created}
Status: {status}"""

        questions = {
            "domain": {
                "type": "choice",
                "instructions": "Which life domain does this task belong to?",
                "criteria": {
                    "family": "Family relationships, parenting, children",
                    "finance": "Money, budgeting, bills, banking",
                    "health": "Medical, doctor appointments, wellness",
                    "tech": "Technology, computers, software",
                    "home": "Household, repairs, chores, garden",
                    "work": "Job, career, professional tasks",
                    "media": "Entertainment, books, files, games",
                    "ideas": "Creative projects, brainstorming",
                    "fitness": "Exercise, gym, sports",
                    "education": "Learning, courses, reading",
                    "social": "Friends, networking, social events",
                    "reflection": "Journaling, review, planning",
                    "other": "None of the above categories"
                }
            },
            "priority": {
                "type": "choice",
                "instructions": "How urgent/important is this task?",
                "criteria": {
                    "dormant": "Not currently active, paused",
                    "low": "Can wait weeks, low priority",
                    "medium": "Should do within a week",
                    "high": "Should do today or tomorrow",
                    "critical": "Urgent, must do immediately"
                }
            },
            "lifecycle": {
                "type": "choice",
                "instructions": "What lifecycle stage is this task in?",
                "criteria": {
                    "active": "Currently being worked on",
                    "stalled": "Was active but now stuck",
                    "completed": "Finished and done",
                    "reference": "Information for future reference",
                    "someday": "Maybe someday, not now"
                }
            },
            "sentiment_index": {
                "type": "score",
                "instructions": "Rate the emotional tone of this task",
                "criteria": [
                    "Very negative - dreading or painful",
                    "Negative - unpleasant or annoying",
                    "Neutral - no strong feeling",
                    "Positive - enjoyable or satisfying",
                    "Very positive - excited or meaningful"
                ]
            },
            "has_financial": {
                "type": "noul",
                "instructions": "Does this task involve spending or receiving money?",
                "criteria": {
                    "true": "Involves payment, purchase, bill, refund, or income",
                    "false": "No money involved"
                }
            },
            "has_deadline": {
                "type": "noul",
                "instructions": "Does this task mention a specific deadline or due date?",
                "criteria": {
                    "true": "Has explicit date, deadline, or due date",
                    "false": "No deadline mentioned"
                }
            },
            "is_recurring": {
                "type": "noul",
                "instructions": "Is this a recurring or repeating task?",
                "criteria": {
                    "true": "Weekly, monthly, or other repeating schedule",
                    "false": "One-time task"
                }
            },
            "classification_confidence": {
                "type": "score",
                "instructions": "How confident are you in this classification?",
                "criteria": [
                    "Low confidence - ambiguous or unclear",
                    "Medium confidence - reasonable guess",
                    "High confidence - clear and obvious"
                ]
            }
        }

        result = self.evaluate(state, questions)

        # Transform to match LLMClient.classify_task output format
        sentiment_idx = int(result["sentiment_index"]["score"])
        confidence_idx = result["classification_confidence"]["score"]

        return {
            "domain": result["domain"]["choice"],
            "subdomain": None,  # Jev cannot generate freeform strings
            "entities": [],  # Jev cannot extract arbitrary entity names
            "sentiment": self.SENTIMENTS[sentiment_idx] if 0 <= sentiment_idx < 5 else "neutral",
            "priority": result["priority"]["choice"],
            "lifecycle": result["lifecycle"]["choice"],
            "lifecycle_note": None,
            "domain_note": None,
            "estimated_cost": None,  # Jev cannot generate amounts
            "summary": None,  # Jev cannot generate summaries
            # Jev-specific additions
            "confidence": result["classification_confidence"].get("confidence", 0.5),
            "domain_confidence": result["domain"].get("confidence", 0.5),
            "priority_confidence": result["priority"].get("confidence", 0.5),
            "has_financial": result["has_financial"]["noul"],
            "has_deadline": result["has_deadline"]["noul"],
            "is_recurring": result["is_recurring"]["noul"],
        }

    def should_escalate_to_llm(self, classification: Dict[str, Any]) -> bool:
        """Check if Jev confidence is too low and should escalate to full LLM.

        Uses domain confidence (from choice question) rather than the
        classification_confidence score, since choice confidence indicates
        how decisive the domain selection was.
        """
        # Use domain confidence (how peaked the distribution is)
        domain_conf = classification.get("domain_confidence", 0.5)
        # Lower threshold since we want to apply more Jev classifications
        # Jev's choice confidence is typically lower for ambiguous cases
        return domain_conf < 0.5


class LLMClient:
    """Client for LLM inference with OpenRouter free and opencode.ai zen tiers."""

    # Free tier — OpenRouter
    OPENROUTER_BASE_URL = "https://openrouter.ai/api/v1"
    FREE_MODEL = "nvidia/nemotron-3-super-120b-a12b:free"

    # Zen tier — opencode.ai (opencode-go primary, opencode-zen fallback)
    OPENCODE_GO_BASE_URL = "https://opencode.ai/zen/go/v1"
    OPENCODE_ZEN_BASE_URL = "https://opencode.ai/zen/v1"
    ZEN_MODEL = "qwen3.7-plus"

    def __init__(self):
        self.client = httpx.Client(timeout=120.0)
        cfg_dir = Path.home() / ".config" / "opencode"
        self.free_key = os.environ.get("OPENROUTER_API_KEY") or self._read_first_line(
            cfg_dir / ".openrouter-key"
        )
        self.opencode_key = (
            os.environ.get("OPENCODE_API_KEY")
            or os.environ.get("OPENCODE_GO_API_KEY")
            or self._read_first_line(cfg_dir / ".opencode-key")
        )
        self.zen_key = os.environ.get("OPENCODE_ZEN_API_KEY")

    @staticmethod
    def _read_first_line(path: Path) -> Optional[str]:
        try:
            return path.read_text().strip()
        except (FileNotFoundError, OSError):
            return None

    def _call_api(
        self,
        base_url: str,
        model: str,
        messages: List[Dict[str, str]],
        api_key: str,
        temperature: float = 0.3,
        max_tokens: int = 2048,
    ) -> Optional[str]:
        """Make an OpenAI-compatible API call."""
        url = f"{base_url.rstrip('/')}/chat/completions"
        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        # opencode-go requires a session header for request routing
        if "opencode.ai/zen/go" in base_url:
            headers["x-opencode-session"] = "mybrain"
        payload = {
            "model": model,
            "messages": messages,
            "temperature": temperature,
            "max_tokens": max_tokens,
        }

        try:
            resp = self.client.post(url, json=payload, headers=headers)
            resp.raise_for_status()
            data = resp.json()
            return data["choices"][0]["message"]["content"]
        except httpx.HTTPStatusError as e:
            if e.response.status_code == 429:
                time.sleep(5)
                return self._call_api(base_url, model, messages, api_key, temperature, max_tokens)
            return None
        except Exception:
            return None

    def _call_free(
        self,
        messages: list[dict[str, str]],
        temperature: float = 0.3,
        max_tokens: int = 2048,
    ) -> Optional[str]:
        """Call free tier via OpenRouter."""
        if not self.free_key:
            return None
        return self._call_api(
            self.OPENROUTER_BASE_URL,
            self.FREE_MODEL,
            messages,
            self.free_key,
            temperature,
            max_tokens,
        )

    def _call_zen(
        self,
        messages: list[dict[str, str]],
        temperature: float = 0.3,
        max_tokens: int = 2048,
    ) -> Optional[str]:
        """Call zen tier via opencode.ai — try opencode-go first, fall back to opencode-zen."""
        if self.opencode_key:
            result = self._call_api(
                self.OPENCODE_GO_BASE_URL,
                self.ZEN_MODEL,
                messages,
                self.opencode_key,
                temperature,
                max_tokens,
            )
            if result is not None:
                return result
        if self.zen_key:
            return self._call_api(
                self.OPENCODE_ZEN_BASE_URL,
                self.ZEN_MODEL,
                messages,
                self.zen_key,
                temperature,
                max_tokens,
            )
        return None

    def _call_api_json(
        self,
        base_url: str,
        model: str,
        messages: List[Dict[str, str]],
        api_key: str,
        temperature: float = 0.3,
        max_tokens: Optional[int] = 2048,
    ) -> tuple[Optional[str], Optional[str]]:
        """Like _call_api but returns (content, finish_reason). max_tokens=None
        omits the cap so a provider can use its model-specific output limit
        (used for the one bounded retry after a length truncation)."""
        url = f"{base_url.rstrip('/')}/chat/completions"
        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        # opencode-go requires a session header for request routing
        if "opencode.ai/zen/go" in base_url:
            headers["x-opencode-session"] = "mybrain"
        payload: Dict[str, Any] = {
            "model": model,
            "messages": messages,
            "temperature": temperature,
        }
        if max_tokens is not None:
            payload["max_tokens"] = max_tokens

        try:
            resp = self.client.post(url, json=payload, headers=headers)
            resp.raise_for_status()
            data = resp.json()
            choice = data["choices"][0]
            return choice["message"]["content"], choice.get("finish_reason")
        except httpx.HTTPStatusError as e:
            if e.response.status_code == 429:
                time.sleep(5)
                return self._call_api_json(
                    base_url, model, messages, api_key, temperature, max_tokens
                )
            return None, None
        except Exception:
            return None, None

    def _json_with_retry(
        self,
        base_url: str,
        model: str,
        key: str,
        messages: List[Dict[str, str]],
        temperature: float = 0.3,
        max_tokens: Optional[int] = 2048,
    ) -> Optional[Dict[str, Any]]:
        """One JSON call with truncation detection: if finish_reason == 'length'
        (JSON was cut at the token cap), retry once WITHOUT the cap so the provider
        can finish, then parse. Returns parsed dict or None."""
        content, finish = self._call_api_json(
            base_url, model, messages, key, temperature, max_tokens
        )
        if content is None:
            return None
        if finish == "length":
            content2, _ = self._call_api_json(base_url, model, messages, key, temperature, None)
            if content2 is not None:
                content = content2
        try:
            return _parse_llm_json(content)
        except (json.JSONDecodeError, ValueError, TypeError):
            return None

    def _call_free_json(
        self,
        messages: list[dict[str, str]],
        temperature: float = 0.3,
        max_tokens: int = 2048,
    ) -> Optional[Dict[str, Any]]:
        """Free-tier JSON call with truncation detection + one bounded retry."""
        if not self.free_key:
            return None
        return self._json_with_retry(
            self.OPENROUTER_BASE_URL,
            self.FREE_MODEL,
            self.free_key,
            messages,
            temperature,
            max_tokens,
        )

    def _call_zen_json(
        self,
        messages: list[dict[str, str]],
        temperature: float = 0.3,
        max_tokens: int = 2048,
    ) -> Optional[Dict[str, Any]]:
        """Zen-tier JSON call with truncation detection + one bounded retry.
        Tries opencode-go first, falls back to opencode-zen."""
        if self.opencode_key:
            result = self._json_with_retry(
                self.OPENCODE_GO_BASE_URL,
                self.ZEN_MODEL,
                self.opencode_key,
                messages,
                temperature,
                max_tokens,
            )
            if result is not None:
                return result
        if self.zen_key:
            return self._json_with_retry(
                self.OPENCODE_ZEN_BASE_URL,
                self.ZEN_MODEL,
                self.zen_key,
                messages,
                temperature,
                max_tokens,
            )
        return None

    def classify_task(
        self, title: str, notes: str, list_name: str, created: str, status: str
    ) -> Optional[Dict[str, Any]]:
        """Classify a single task via free model."""
        prompt = f"""Classify this task from my personal todo list:

Task: {title}
Notes: {notes}
List: {list_name}
Created: {created}
Status: {status}

Return ONLY valid JSON with these fields:
- domain: one of [family, finance, health, tech, home, work, media, ideas, fitness, education, social, reflection]
- subdomain: string (more specific category)
- entities: list of {{"name": str, "type": "person"|"place"|"concept"|"tool"|"organization"}}
- sentiment: one of [very_negative, negative, neutral, positive, very_positive]
- priority: one of [critical, high, medium, low, dormant]
- lifecycle: one of [active, stalled, completed, reference, someday]
- estimated_cost: float or null
- summary: string (1-sentence essence)

JSON:"""

        messages = [
            {
                "role": "system",
                "content": "You are a personal task classifier. Return ONLY valid JSON.",
            },
            {"role": "user", "content": prompt},
        ]

        return self._call_zen_json(messages)

    def classify_task_jev(
        self, 
        title: str, 
        notes: str, 
        list_name: str, 
        created: str, 
        status: str,
        escalate_on_low_confidence: bool = True
    ) -> Optional[Dict[str, Any]]:
        """
        Classify task using Jev for structured decisions with optional LLM fallback.

        Strategy:
        1. Jev classifies domain, priority, lifecycle, sentiment, flags
        2. If Jev confidence < 0.7, escalate to full LLM classification
        3. Otherwise, return Jev's classification

        Args:
            title: Task title
            notes: Task notes/description
            list_name: Google Tasks list name
            created: Creation timestamp
            status: Task status
            escalate_on_low_confidence: If True, fall back to LLM on low confidence

        Returns:
            Classification dict compatible with classify_task output
        """
        try:
            jev = JevClient()
            result = jev.classify_task(title, notes, list_name, created, status)

            # Check if we should escalate to full LLM
            if escalate_on_low_confidence and jev.should_escalate_to_llm(result):
                print(f"    Domain confidence low ({result.get('domain_confidence', 0):.2f}), escalating to LLM")
                return self.classify_task(title, notes, list_name, created, status)

            return result

        except ValueError as e:
            # Jev API error, fall back to LLM
            print(f"    Jev error: {e}, falling back to LLM")
            return self.classify_task(title, notes, list_name, created, status)
        except Exception as e:
            print(f"    Jev unexpected error: {e}, falling back to LLM")
            return self.classify_task(title, notes, list_name, created, status)

    def generate_daily_standup(self, context: Dict[str, Any]) -> Optional[str]:
        """Generate daily standup markdown."""
        prompt = f"""You are a personal life dashboard system. Generate a daily standup report.

Today's date: {context.get("date", "unknown")}

Critical tasks:
{_dumps(context.get("critical_tasks", []), indent=2)}

Stalled tasks needing revival:
{_dumps(context.get("stalled_tasks", []), indent=2)}

Recent recommendations:
{_dumps(context.get("recommendations", []), indent=2)}

Budget:
{_dumps(context.get("budget", {}), indent=2)}

On this day in prior years:
{_dumps(context.get("on_this_day", []), indent=2)}

Cross-domain connections found:
{_dumps(context.get("connections", []), indent=2)}

Yesterday's plan:
{_dumps(context.get("yesterday_plan", []), indent=2)}

Generate a concise daily standup markdown page with sections:
1. 🔴 Critical items
2. 🟡 Stalled revival
3. 🔗 Cross-domain connections
4. 💰 Affordability this week
5. 📅 On this day
6. ✅ Yesterday's status

Use [[wiki-link]] format for task references."""

        messages = [
            {
                "role": "system",
                "content": "You are a personal life dashboard. Output clean markdown.",
            },
            {"role": "user", "content": prompt},
        ]
        return self._call_free(messages, temperature=0.7, max_tokens=4096)

    def generate_weekly_synthesis(self, context: Dict[str, Any]) -> Optional[str]:
        """Generate weekly synthesis using zen model."""
        prompt = f"""You are a personal life synthesis system. Generate a weekly report.

Week: {context.get("week", "unknown")}

Task changes this week:
{_dumps(context.get("task_changes", []), indent=2)}

Domain pulse:
{_dumps(context.get("domain_pulse", {}), indent=2)}

Financial pulse:
{_dumps(context.get("financial_pulse", {}), indent=2)}

Cross-domain patterns:
{_dumps(context.get("patterns", []), indent=2)}

Recommendation response:
{_dumps(context.get("recommendation_stats", {}), indent=2)}

Generate a markdown weekly synthesis with:
1. Executive summary (2 paragraphs)
2. Domain pulse table
3. Financial pulse
4. Patterns detected (cross-domain)
5. Priority rebalance suggestions
6. Recommendations for this week
7. Domain-specific action plans (Family, Finance, Tech)
8. Review checklist

Use [[wiki-link]] format."""

        messages = [
            {
                "role": "system",
                "content": "You are a personal life synthesis engine. Output clean markdown with actionable insights.",
            },
            {"role": "user", "content": prompt},
        ]
