    def rehearse_gambit(
        self,
        goal_name: str,
        goal_description: str,
        gambit_name: str,
        gambit_description: str,
        actors: List[Dict[str, str]],
        max_rounds: int = 6,
    ) -> Optional[Dict[str, Any]]:
        """Rehearse a candidate gambit: one bounded in-context multi-actor
        role-play that projects how the bet plays out, returning a revised
        risk/reward score and expected outcome. Free tier, non-fatal.

        This is MiroFish's 'rehearse the future before you bet' idea at a
        tiny token cost (one call, capped actors/rounds) instead of a real
        multi-agent OASIS loop."""
        if not actors:
            return None
        actors_text = "\n".join(
            f"- {a.get('name', '?')} ({a.get('type', 'unknown')})" for a in actors[:6]
        )
        prompt = f"""You are a strategic rehearsal engine. We are about to BET on a gambit.
Role-play how it plays out so we can score it before committing.

Goal: {goal_name}
Goal description: {goal_description}

Gambit under test: {gambit_name}
What it does: {gambit_description or "(no description)"}

Actors (derived from recent signals, will react to the gambit being taken):
{actors_text}

Simulate {max_rounds} rounds of these actors reacting. For each actor, note the
initial stance and the FINAL stance after the rounds, plus the single key driver
of the shift. Then judge the overall expected outcome, the strongest
counterarguments, and REVISED risk/reward scores reflecting what the rehearsal
revealed (1=low, 10=high).

Return ONLY valid JSON with this structure:
{{
  "rounds": <int>,
  "stances": [
    {{"actor": str, "initial_stance": str, "final_stance": str, "key_shift": str}}
  ],
  "expected_outcome": str,
  "counterarguments": [str],
  "revised_risk_score": int 1-10,
  "revised_reward_score": int 1-10,
  "confidence": float 0-1
}}

JSON:"""

        messages = [
            {
                "role": "system",
                "content": "You are a strategic rehearsal engine. Return ONLY valid JSON.",
            },
            {"role": "user", "content": prompt},
        ]

        return self._call_free_json(messages, temperature=0.5, max_tokens=4096)

